{{Artes culinarias/Datos de receta
|comensales = 8
|tiempo = 20 minutos
|dificultad = 2
|ingredientes = 
* 500 centilitros de {{ing|leche}}
* 2 dientes de {{ing|ajo}}
* 1 cucharada pequeña de {{ing|sal}}
* 250 centilitros de {{ing|aceite de girasol}}
* 2 ramas de {{ing|perejil}}
|procedimiento = 
# Lavar y pelar ajos.
# Echar la leche, los ajos, el perejil y la sal en el recipiente. A continuación se a muele todo.
# Una vez molido, se vierte poco a poco el aceite sin parar de revolver hasta coger el espesor deseado y ya tenemos la mayonesa ali-oli!!
}}


